     1→//! Provides the `ObservedBlockProducers` struct which allows for rejecting gossip blocks from
     2→//! validators that have already produced a block.
     3→
     4→use std::collections::hash_map::Entry;
     5→use std::collections::{HashMap, HashSet};
     6→use std::marker::PhantomData;
     7→use types::{BeaconBlockRef, Epoch, EthSpec, Hash256, Slot, Unsigned};
     8→
     9→#[derive(Debug, PartialEq)]
    10→pub enum Error {
    11→    /// The slot of the provided block is prior to finalization and should not have been provided
    12→    /// to this function. This is an internal error.
    13→    FinalizedBlock { slot: Slot, finalized_slot: Slot },
    14→    /// The function to obtain a set index failed, this is an internal error.
    15→    ValidatorIndexTooHigh(u64),
    16→}
    17→
    18→#[derive(Eq, Hash, PartialEq, Debug, Default)]
    19→pub struct ProposalKey {
    20→    pub slot: Slot,
    21→    pub proposer: u64,
    22→}
    23→
    24→impl ProposalKey {
    25→    pub fn new(proposer: u64, slot: Slot) -> Self {
    26→        Self { slot, proposer }
    27→    }
    28→}
    29→
    30→/// Maintains a cache of observed `(block.slot, block.proposer)`.
    31→///
    32→/// The cache supports pruning based upon the finalized epoch. It does not automatically prune, you
    33→/// must call `Self::prune` manually.
    34→///
    35→/// The maximum size of the cache is determined by `slots_since_finality *
    36→/// VALIDATOR_REGISTRY_LIMIT`. This is quite a large size, so it's important that upstream
    37→/// functions only use this cache for blocks with a valid signature. Only allowing valid signed
    38→/// blocks reduces the theoretical maximum size of this cache to `slots_since_finality *
    39→/// active_validator_count`, however in reality that is more like `slots_since_finality *
    40→/// known_distinct_shufflings` which is much smaller.
    41→pub struct ObservedBlockProducers<E: EthSpec> {
    42→    finalized_slot: Slot,
    43→    items: HashMap<ProposalKey, HashSet<Hash256>>,
    44→    _phantom: PhantomData<E>,
    45→}
    46→
    47→impl<E: EthSpec> Default for ObservedBlockProducers<E> {
    48→    /// Instantiates `Self` with `finalized_slot == 0`.
    49→    fn default() -> Self {
    50→        Self {
    51→            finalized_slot: Slot::new(0),
    52→            items: HashMap::new(),
    53→            _phantom: PhantomData,
    54→        }
    55→    }
    56→}
    57→
    58→pub enum SeenBlock {
    59→    Duplicate,
    60→    Slashable,
    61→    UniqueNonSlashable,
    62→}
    63→
    64→impl SeenBlock {
    65→    pub fn proposer_previously_observed(self) -> bool {
    66→        match self {
    67→            Self::Duplicate | Self::Slashable => true,
    68→            Self::UniqueNonSlashable => false,
    69→        }
    70→    }
    71→    pub fn is_slashable(&self) -> bool {
    72→        matches!(self, Self::Slashable)
    73→    }
    74→}
    75→
    76→impl<E: EthSpec> ObservedBlockProducers<E> {
    77→    /// Observe that the `block` was produced by `block.proposer_index` at `block.slot`. This will
    78→    /// update `self` so future calls to it indicate that this block is known.
    79→    ///
    80→    /// The supplied `block` **MUST** be signature verified (see struct-level documentation).
    81→    ///
    82→    /// ## Errors
    83→    ///
    84→    /// - `block.proposer_index` is greater than `VALIDATOR_REGISTRY_LIMIT`.
    85→    /// - `block.slot` is equal to or less than the latest pruned `finalized_slot`.
    86→    pub fn observe_proposal(
    87→        &mut self,
    88→        block_root: Hash256,
    89→        block: BeaconBlockRef<'_, E>,
    90→    ) -> Result<SeenBlock, Error> {
    91→        self.sanitize_block(block)?;
    92→
    93→        let key = ProposalKey {
    94→            slot: block.slot(),
    95→            proposer: block.proposer_index(),
    96→        };
    97→
    98→        let entry = self.items.entry(key);
    99→
   100→        let slashable_proposal = match entry {
   101→            Entry::Occupied(mut occupied_entry) => {
   102→                let block_roots = occupied_entry.get_mut();
   103→                let newly_inserted = block_roots.insert(block_root);
   104→
   105→                let is_equivocation = block_roots.len() > 1;
   106→
   107→                if is_equivocation {
   108→                    SeenBlock::Slashable
   109→                } else if !newly_inserted {
   110→                    SeenBlock::Duplicate
   111→                } else {
   112→                    SeenBlock::UniqueNonSlashable
   113→                }
   114→            }
   115→            Entry::Vacant(vacant_entry) => {
   116→                let block_roots = HashSet::from([block_root]);
   117→                vacant_entry.insert(block_roots);
   118→
   119→                SeenBlock::UniqueNonSlashable
   120→            }
   121→        };
   122→
   123→        Ok(slashable_proposal)
   124→    }
   125→
   126→    /// Returns `Ok(true)` if the `block` has been observed before, `Ok(false)` if not. Does not
   127→    /// update the cache, so calling this function multiple times will continue to return
   128→    /// `Ok(false)`, until `Self::observe_proposer` is called.
   129→    ///
   130→    /// ## Errors
   131→    ///
   132→    /// - `block.proposer_index` is greater than `VALIDATOR_REGISTRY_LIMIT`.
   133→    /// - `block.slot` is equal to or less than the latest pruned `finalized_slot`.
   134→    pub fn proposer_has_been_observed(
   135→        &self,
   136→        block: BeaconBlockRef<'_, E>,
   137→        block_root: Hash256,
   138→    ) -> Result<SeenBlock, Error> {
   139→        self.sanitize_block(block)?;
   140→
   141→        let key = ProposalKey {
   142→            slot: block.slot(),
   143→            proposer: block.proposer_index(),
   144→        };
   145→
   146→        if let Some(block_roots) = self.items.get(&key) {
   147→            let block_already_known = block_roots.contains(&block_root);
   148→            let no_prev_known_blocks =
   149→                block_roots.difference(&HashSet::from([block_root])).count() == 0;
   150→
   151→            if !no_prev_known_blocks {
   152→                Ok(SeenBlock::Slashable)
   153→            } else if block_already_known {
   154→                Ok(SeenBlock::Duplicate)
   155→            } else {
   156→                Ok(SeenBlock::UniqueNonSlashable)
   157→            }
   158→        } else {
   159→            Ok(SeenBlock::UniqueNonSlashable)
   160→        }
   161→    }
   162→
   163→    /// Returns `Ok(())` if the given `block` is sane.
   164→    fn sanitize_block(&self, block: BeaconBlockRef<'_, E>) -> Result<(), Error> {
   165→        if block.proposer_index() >= E::ValidatorRegistryLimit::to_u64() {
   166→            return Err(Error::ValidatorIndexTooHigh(block.proposer_index()));
   167→        }
   168→
   169→        let finalized_slot = self.finalized_slot;
   170→        if finalized_slot > 0 && block.slot() <= finalized_slot {
   171→            return Err(Error::FinalizedBlock {
   172→                slot: block.slot(),
   173→                finalized_slot,
   174→            });
   175→        }
   176→
   177→        Ok(())
   178→    }
   179→
   180→    /// Removes all observations of blocks equal to or earlier than `finalized_slot`.
   181→    ///
   182→    /// Stores `finalized_slot` in `self`, so that `self` will reject any block that has a slot
   183→    /// equal to or less than `finalized_slot`.
   184→    ///
   185→    /// No-op if `finalized_slot == 0`.
   186→    pub fn prune(&mut self, finalized_slot: Slot) {
   187→        if finalized_slot == 0 {
   188→            return;
   189→        }
   190→
   191→        self.finalized_slot = finalized_slot;
   192→        self.items.retain(|key, _| key.slot > finalized_slot);
   193→    }
   194→
   195→    /// Returns `true` if the given `validator_index` has been stored in `self` at `epoch`.
   196→    ///
   197→    /// This is useful for doppelganger detection.
   198→    pub fn index_seen_at_epoch(&self, validator_index: u64, epoch: Epoch) -> bool {
   199→        self.items.iter().any(|(key, _)| {
   200→            key.slot.epoch(E::slots_per_epoch()) == epoch && key.proposer == validator_index
   201→        })
   202→    }
   203→}
   204→
   205→#[cfg(test)]
   206→mod tests {
   207→    use super::*;
   208→    use types::{BeaconBlock, MainnetEthSpec};
   209→
   210→    type E = MainnetEthSpec;
   211→
   212→    fn get_block(slot: u64, proposer: u64) -> BeaconBlock<E> {
   213→        let mut block = BeaconBlock::empty(&E::default_spec());
   214→        *block.slot_mut() = slot.into();
   215→        *block.proposer_index_mut() = proposer;
   216→        block
   217→    }
   218→
   219→    #[test]
   220→    fn pruning() {
   221→        let mut cache = ObservedBlockProducers::default();
   222→
   223→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   224→        assert_eq!(cache.items.len(), 0, "no slots should be present");
   225→
   226→        // Slot 0, proposer 0
   227→        let block_a = get_block(0, 0);
   228→        let block_root = block_a.canonical_root();
   229→
   230→        assert_eq!(
   231→            cache
   232→                .observe_proposal(block_root, block_a.to_ref())
   233→                .map(SeenBlock::proposer_previously_observed),
   234→            Ok(false),
   235→            "can observe proposer, indicates proposer unobserved"
   236→        );
   237→
   238→        /*
   239→         * Preconditions.
   240→         */
   241→
   242→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   243→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   244→        assert_eq!(
   245→            cache
   246→                .items
   247→                .get(&ProposalKey {
   248→                    slot: Slot::new(0),
   249→                    proposer: 0
   250→                })
   251→                .expect("slot zero should be present")
   252→                .len(),
   253→            1,
   254→            "only one proposer should be present"
   255→        );
   256→
   257→        /*
   258→         * Check that a prune at the genesis slot does nothing.
   259→         */
   260→
   261→        cache.prune(Slot::new(0));
   262→
   263→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   264→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   265→        assert_eq!(
   266→            cache
   267→                .items
   268→                .get(&ProposalKey {
   269→                    slot: Slot::new(0),
   270→                    proposer: 0
   271→                })
   272→                .expect("slot zero should be present")
   273→                .len(),
   274→            1,
   275→            "only one proposer should be present"
   276→        );
   277→
   278→        /*
   279→         * Check that a prune empties the cache
   280→         */
   281→
   282→        cache.prune(E::slots_per_epoch().into());
   283→        assert_eq!(
   284→            cache.finalized_slot,
   285→            Slot::from(E::slots_per_epoch()),
   286→            "finalized slot is updated"
   287→        );
   288→        assert_eq!(cache.items.len(), 0, "no items left");
   289→
   290→        /*
   291→         * Check that we can't insert a finalized block
   292→         */
   293→
   294→        // First slot of finalized epoch, proposer 0
   295→        let block_b = get_block(E::slots_per_epoch(), 0);
   296→        let block_root_b = block_b.canonical_root();
   297→
   298→        assert_eq!(
   299→            cache
   300→                .observe_proposal(block_root_b, block_b.to_ref())
   301→                .map(SeenBlock::proposer_previously_observed),
   302→            Err(Error::FinalizedBlock {
   303→                slot: E::slots_per_epoch().into(),
   304→                finalized_slot: E::slots_per_epoch().into(),
   305→            }),
   306→            "cant insert finalized block"
   307→        );
   308→
   309→        assert_eq!(cache.items.len(), 0, "block was not added");
   310→
   311→        /*
   312→         * Check that we _can_ insert a non-finalized block
   313→         */
   314→
   315→        let three_epochs = E::slots_per_epoch() * 3;
   316→
   317→        // First slot of finalized epoch, proposer 0
   318→        let block_b = get_block(three_epochs, 0);
   319→
   320→        assert_eq!(
   321→            cache
   322→                .observe_proposal(block_root_b, block_b.to_ref())
   323→                .map(SeenBlock::proposer_previously_observed),
   324→            Ok(false),
   325→            "can insert non-finalized block"
   326→        );
   327→
   328→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   329→        assert_eq!(
   330→            cache
   331→                .items
   332→                .get(&ProposalKey {
   333→                    slot: Slot::new(three_epochs),
   334→                    proposer: 0
   335→                })
   336→                .expect("the three epochs slot should be present")
   337→                .len(),
   338→            1,
   339→            "only one proposer should be present"
   340→        );
   341→
   342→        /*
   343→         * Check that a prune doesnt wipe later blocks
   344→         */
   345→
   346→        let two_epochs = E::slots_per_epoch() * 2;
   347→        cache.prune(two_epochs.into());
   348→
   349→        assert_eq!(
   350→            cache.finalized_slot,
   351→            Slot::from(two_epochs),
   352→            "finalized slot is updated"
   353→        );
   354→
   355→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   356→        assert_eq!(
   357→            cache
   358→                .items
   359→                .get(&ProposalKey {
   360→                    slot: Slot::new(three_epochs),
   361→                    proposer: 0
   362→                })
   363→                .expect("the three epochs slot should be present")
   364→                .len(),
   365→            1,
   366→            "only one proposer should be present"
   367→        );
   368→    }
   369→
   370→    #[test]
   371→    fn simple_observations() {
   372→        let mut cache = ObservedBlockProducers::default();
   373→
   374→        // Slot 0, proposer 0
   375→        let block_a = get_block(0, 0);
   376→        let block_root_a = block_a.canonical_root();
   377→
   378→        assert_eq!(
   379→            cache
   380→                .proposer_has_been_observed(block_a.to_ref(), block_a.canonical_root())
   381→                .map(|x| x.proposer_previously_observed()),
   382→            Ok(false),
   383→            "no observation in empty cache"
   384→        );
   385→        assert_eq!(
   386→            cache
   387→                .observe_proposal(block_root_a, block_a.to_ref())
   388→                .map(SeenBlock::proposer_previously_observed),
   389→            Ok(false),
   390→            "can observe proposer, indicates proposer unobserved"
   391→        );
   392→        assert_eq!(
   393→            cache
   394→                .proposer_has_been_observed(block_a.to_ref(), block_a.canonical_root())
   395→                .map(|x| x.proposer_previously_observed()),
   396→            Ok(true),
   397→            "observed block is indicated as true"
   398→        );
   399→        assert_eq!(
   400→            cache
   401→                .observe_proposal(block_root_a, block_a.to_ref())
   402→                .map(SeenBlock::proposer_previously_observed),
   403→            Ok(true),
   404→            "observing again indicates true"
   405→        );
   406→
   407→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   408→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   409→        assert_eq!(
   410→            cache
   411→                .items
   412→                .get(&ProposalKey {
   413→                    slot: Slot::new(0),
   414→                    proposer: 0
   415→                })
   416→                .expect("slot zero should be present")
   417→                .len(),
   418→            1,
   419→            "only one proposer should be present"
   420→        );
   421→
   422→        // Slot 1, proposer 0
   423→        let block_b = get_block(1, 0);
   424→        let block_root_b = block_b.canonical_root();
   425→
   426→        assert_eq!(
   427→            cache
   428→                .proposer_has_been_observed(block_b.to_ref(), block_b.canonical_root())
   429→                .map(|x| x.proposer_previously_observed()),
   430→            Ok(false),
   431→            "no observation for new slot"
   432→        );
   433→        assert_eq!(
   434→            cache
   435→                .observe_proposal(block_root_b, block_b.to_ref())
   436→                .map(SeenBlock::proposer_previously_observed),
   437→            Ok(false),
   438→            "can observe proposer for new slot, indicates proposer unobserved"
   439→        );
   440→        assert_eq!(
   441→            cache
   442→                .proposer_has_been_observed(block_b.to_ref(), block_b.canonical_root())
   443→                .map(|x| x.proposer_previously_observed()),
   444→            Ok(true),
   445→            "observed block in slot 1 is indicated as true"
   446→        );
   447→        assert_eq!(
   448→            cache
   449→                .observe_proposal(block_root_b, block_b.to_ref())
   450→                .map(SeenBlock::proposer_previously_observed),
   451→            Ok(true),
   452→            "observing slot 1 again indicates true"
   453→        );
   454→
   455→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   456→        assert_eq!(cache.items.len(), 2, "two slots should be present");
   457→        assert_eq!(
   458→            cache
   459→                .items
   460→                .get(&ProposalKey {
   461→                    slot: Slot::new(0),
   462→                    proposer: 0
   463→                })
   464→                .expect("slot zero should be present")
   465→                .len(),
   466→            1,
   467→            "only one proposer should be present in slot 0"
   468→        );
   469→        assert_eq!(
   470→            cache
   471→                .items
   472→                .get(&ProposalKey {
   473→                    slot: Slot::new(1),
   474→                    proposer: 0
   475→                })
   476→                .expect("slot zero should be present")
   477→                .len(),
   478→            1,
   479→            "only one proposer should be present in slot 1"
   480→        );
   481→
   482→        // Slot 0, proposer 1
   483→        let block_c = get_block(0, 1);
   484→        let block_root_c = block_c.canonical_root();
   485→
   486→        assert_eq!(
   487→            cache
   488→                .proposer_has_been_observed(block_c.to_ref(), block_c.canonical_root())
   489→                .map(|x| x.proposer_previously_observed()),
